CREATE TABLE IF NOT EXISTS hhba_library_energy_recruitment_candidates (
 id TEXT PRIMARY KEY,
 collection_sequence INTEGER NOT NULL UNIQUE CHECK(collection_sequence BETWEEN 1 AND 200),
 employer_display_name TEXT NOT NULL,
 candidate_url TEXT NOT NULL UNIQUE,
 section_id TEXT NOT NULL REFERENCES hhba_library_hall_sections(section_id),
 hall_id TEXT NOT NULL DEFAULT 'energy' CHECK(hall_id='energy'),
 entry_kind TEXT NOT NULL CHECK(entry_kind IN ('ATS','CAREERS','NOTICE','DISCOVERY')),
 parent_group TEXT NOT NULL,
 source_status TEXT NOT NULL DEFAULT 'UNVERIFIED' CHECK(source_status IN ('UNVERIFIED','REJECTED','REVIEWED')),
 batch_id TEXT NOT NULL DEFAULT 'ENERGY_BATCH_001_100',
 collected_at TEXT NOT NULL DEFAULT '2026-11-11'
);
CREATE INDEX IF NOT EXISTS idx_hhba_energy_candidates_section ON hhba_library_energy_recruitment_candidates(section_id,source_status);
